using System;using System.Collections.Generic;using System.IO;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;
namespace LWS.TruckSubmarine.Editor {
 public static class SubmarineArt {
  public const string Folder="TruckSubmarine";
  sealed class Surface {public readonly List<Vector3>v=new List<Vector3>();public readonly List<int>t=new List<int>();public void Tri(Vector3 a,Vector3 b,Vector3 c){int i=v.Count;v.Add(a);v.Add(b);v.Add(c);t.Add(i);t.Add(i+1);t.Add(i+2);}public void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d){Tri(a,b,c);Tri(a,c,d);}public Mesh Mesh(string name){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(v);m.SetTriangles(t,0);var uv=new List<Vector2>();foreach(var p in v)uv.Add(new Vector2(p.x+p.z*.25f,p.y+p.z*.2f)*.15f);m.SetUVs(0,uv);m.RecalculateNormals();m.RecalculateBounds();return m;}}
  static Mesh Save(string name,Func<Mesh> create){string dir="Assets/"+Folder+"/Art";Directory.CreateDirectory(dir);string path=dir+"/"+name+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing!=null)return existing;var mesh=create();mesh.name=name;AssetDatabase.CreateAsset(mesh,path);return mesh;}
  public static GameObject Model(string name,Transform parent,Mesh mesh,Material material,Vector3 p){var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(parent,false);g.transform.localPosition=p;g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<MeshRenderer>().sharedMaterial=material;return g;}
  public static Mesh Box(string name,Vector3 size)=>Save(name,()=>{var s=new Surface();var e=size*.5f;float bevel=Mathf.Min(e.x,e.y,e.z)*.12f;
   void tri(Vector3 a,Vector3 b,Vector3 c){if(Vector3.Dot(Vector3.Cross(b-a,c-a),a+b+c)<0)s.Tri(a,c,b);else s.Tri(a,b,c);}
   void quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d){tri(a,b,c);tri(a,c,d);}
   for(int axis=0;axis<3;axis++)for(int side=-1;side<=1;side+=2){Vector3 n=Vector3.zero,a=Vector3.zero,b=Vector3.zero;n[axis]=e[axis]*side;a[(axis+1)%3]=e[(axis+1)%3]-bevel;b[(axis+2)%3]=e[(axis+2)%3]-bevel;quad(n-a-b,n+a-b,n+a+b,n-a+b);}
   for(int axis=0;axis<3;axis++)for(int j=-1;j<=1;j+=2)for(int k=-1;k<=1;k+=2){int a=(axis+1)%3,b=(axis+2)%3;Vector3 p=Vector3.zero,q=Vector3.zero,u=Vector3.zero,v=Vector3.zero;p[axis]=v[axis]=-e[axis]+bevel;q[axis]=u[axis]=e[axis]-bevel;p[a]=q[a]=e[a]*j;p[b]=q[b]=(e[b]-bevel)*k;u[a]=v[a]=(e[a]-bevel)*j;u[b]=v[b]=e[b]*k;quad(p,q,u,v);}
   for(int x=-1;x<=1;x+=2)for(int y=-1;y<=1;y+=2)for(int z=-1;z<=1;z+=2)tri(new Vector3(e.x*x,(e.y-bevel)*y,(e.z-bevel)*z),new Vector3((e.x-bevel)*x,e.y*y,(e.z-bevel)*z),new Vector3((e.x-bevel)*x,(e.y-bevel)*y,e.z*z));return s.Mesh(name);});
  public static Mesh Lathe(string name,Vector2[] profile,int sides=24)=>Save(name,()=>{var s=new Surface();for(int j=0;j<profile.Length-1;j++)for(int i=0;i<sides;i++){float a=i*Mathf.PI*2/sides,b=(i+1)*Mathf.PI*2/sides;Vector3 p(float angle,int ring)=>new Vector3(Mathf.Cos(angle)*profile[ring].x,profile[ring].y,Mathf.Sin(angle)*profile[ring].x);s.Quad(p(a,j),p(a,j+1),p(b,j+1),p(b,j));}return s.Mesh(name);});
  public static Mesh Tank()=>Lathe("Riveted elliptical pressure tank",new[]{new Vector2(0,-2.4f),new Vector2(.55f,-2.25f),new Vector2(.8f,-1.9f),new Vector2(.8f,1.9f),new Vector2(.55f,2.25f),new Vector2(0,2.4f)},32);
  public static Mesh Ring()=>Lathe("Machined thick bronze ring",new[]{new Vector2(.85f,-.12f),new Vector2(1,-.12f),new Vector2(1,.12f),new Vector2(.85f,.12f),new Vector2(.85f,-.12f)},32);
  public static Mesh Hull(float mass,Vector3 center)=>Save("Closed Archimeds displacement proxy "+mass.ToString("F0"),()=>{var s=new Surface();int rows=10,columns=24;Vector3 p(int y,int x){float phi=-Mathf.PI*.5f+Mathf.PI*y/rows,a=x*Mathf.PI*2/columns;return new Vector3(Mathf.Cos(phi)*Mathf.Cos(a)*1.2f,Mathf.Sin(phi)*.75f,Mathf.Cos(phi)*Mathf.Sin(a)*3);}
   for(int y=0;y<rows;y++)for(int x=0;x<columns;x++){if(y==0)s.Tri(p(y,x),p(y+1,x),p(y+1,x+1));else if(y==rows-1)s.Tri(p(y,x),p(y+1,x),p(y,x+1));else s.Quad(p(y,x),p(y+1,x),p(y+1,x+1),p(y,x+1));}var mesh=s.Mesh("Sealed hydrostatic displacement hull");float volume=Volume(mesh);if(volume<.01f)throw new InvalidOperationException("Closed displacement hull volume required.");float scale=Mathf.Pow((mass/1000)/volume,1f/3);var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++)vertices[i]=vertices[i]*scale+center;mesh.vertices=vertices;mesh.RecalculateBounds();return mesh;});
  public static float Volume(Mesh mesh){double v=0;var p=mesh.vertices;var t=mesh.triangles;for(int i=0;i<t.Length;i+=3)v+=Vector3.Dot(p[t[i]],Vector3.Cross(p[t[i+1]],p[t[i+2]]))/6.0;return (float)Math.Abs(v);}
  public static Mesh Propeller()=>Save("Four swept brass hydrodynamic propeller blades",()=>{var s=new Surface();for(int blade=0;blade<4;blade++){float a=blade*Mathf.PI*.5f;Vector3 p(float radius,float sweep,float z)=>new Vector3(Mathf.Cos(a+sweep)*radius,Mathf.Sin(a+sweep)*radius,z);var x=p(.2f,0,-.12f);var y=p(1.1f,.35f,-.04f);var z=p(1.05f,.85f,.18f);var w=p(.25f,.65f,.12f);s.Quad(x,y,z,w);s.Quad(w,z,y,x);}return s.Mesh("Modeled swept propeller");});
  public static float Floor(float x,float z)=>-35-110*Mathf.Exp(-Mathf.Pow(x/65,2))*Mathf.Exp(-Mathf.Pow((z-80)/125,2))+2*Mathf.Sin(x*.045f)*Mathf.Cos(z*.04f);
  public static Mesh Seabed()=>Save("Ocean trench reefs and shelves 480m",()=>{var s=new Surface();const int n=96;for(int z=0;z<n;z++)for(int x=0;x<n;x++){Vector3 p(int ix,int iz){float wx=-240+ix*5,wz=-240+iz*5;return new Vector3(wx,Floor(wx,wz),wz);}s.Quad(p(x,z),p(x,z+1),p(x+1,z+1),p(x+1,z));}return s.Mesh("Trench and coral shelves");});
  public static Mesh Cave()=>Save("Rounded open ended double wall underwater cave",()=>{var s=new Surface();for(int i=0;i<28;i++){float a=i*Mathf.PI/28,b=(i+1)*Mathf.PI/28;Vector3 p(float t,float radius,float z)=>new Vector3(Mathf.Cos(t)*radius,Mathf.Sin(t)*radius,z);s.Quad(p(a,12,-24),p(a,12,24),p(b,12,24),p(b,12,-24));s.Quad(p(a,16,-24),p(b,16,-24),p(b,16,24),p(a,16,24));s.Quad(p(a,12,-24),p(b,12,-24),p(b,16,-24),p(a,16,-24));s.Quad(p(a,12,24),p(a,16,24),p(b,16,24),p(b,12,24));}return s.Mesh("Real traversable rocky arch cave");});
  public static Mesh SquidMantle()=>Lathe("Giant squid tapered living mantle",new[]{new Vector2(0,-7),new Vector2(1.4f,-5.8f),new Vector2(2.5f,-2),new Vector2(2.8f,2),new Vector2(2.1f,4),new Vector2(.7f,5),new Vector2(0,5.3f)},32);
  public static Mesh Arm()=>Lathe("Articulated tapered sucker bearing squid arm",new[]{new Vector2(0,0),new Vector2(.65f,.2f),new Vector2(.48f,4),new Vector2(.2f,7),new Vector2(0,8)},16);
 }
}
